// Xiaomi standard-auth login and AES-CCM transport adapted from the
// Apache-2.0 ha-cuk-ble implementation; local Windows GATT transport is separate.
namespace Charker;
internal sealed class MiBleSession : IDisposable {
 readonly Func<ushort,byte[],CancellationToken,Task> write;readonly Func<ushort,CancellationToken,Task<byte[]>> read;readonly Func<int> mtu;readonly SemaphoreSlim requests=new(1);readonly CancellationTokenSource life;byte[] keys=[];int tx;readonly MiBleReceiveWindow receiveWindow=new();readonly Dictionary<int,int> propertyCounters=[];ushort sequence=2;TaskCompletionSource<byte[]>? awaiting;ushort awaited;byte requestFlags;
 public event Action<byte[]>? Notification;public event Action<CuktechProtocol.Property[]>? Properties;public event Action<Exception>? Failed;public event Action<string>? Progress;public event Action<string>? Trace;
 static readonly byte[] Ready=[0,0,1,1],Okay=[0,0,1,0],Ack=[0,0,3,0];
 public MiBleSession(Func<ushort,byte[],CancellationToken,Task> write,Func<ushort,CancellationToken,Task<byte[]>> read,Func<int> mtu,CancellationToken ct){this.write=write;this.read=read;this.mtu=mtu;life=CancellationTokenSource.CreateLinkedTokenSource(ct);}
 async Task<byte[]> Read(ushort id){var b=await read(id,life.Token).WaitAsync(TimeSpan.FromSeconds(8),life.Token);if(b.Length==4&&b[0] is >=0xe0 and <=0xe3)throw new IOException("酷态科认证被拒绝，请退出手机米家并核对 Token");return b;}
 async Task Until(ushort id,byte[] expected){for(int i=0;i<64;i++)if((await Read(id)).SequenceEqual(expected))return;throw new InvalidDataException("蓝牙控制响应过多");}
 async Task SendParcel(ushort channel,byte code,byte[] payload,bool auth,int counter=0){int cap=Math.Max(18,mtu()-5)-(auth?0:2),count=(payload.Length+cap-1)/cap;if(count is <1 or >64)throw new InvalidDataException("蓝牙分片数量无效");await write(channel,[0,0,0,code,(byte)count,0],life.Token);await Until(channel,Ready);for(int i=0;i<count;i++){byte[] prefix=auth?[(byte)(i+1),0]:[(byte)(i+1),0,(byte)counter,(byte)(counter>>8)];await write(channel,prefix.Concat(payload.Skip(i*cap).Take(cap)).ToArray(),life.Token);}await Until(channel,Okay);}
 async Task<byte[]> ReceiveAuth(byte expected){var a=await Read(0x19);if(a.Length<4||a[3]!=expected)throw new InvalidDataException("认证响应与请求不匹配");if(a[2]==2){await write(0x19,Ack,life.Token);return a[4..];}if(a[2]!=0||a.Length!=6)throw new InvalidDataException("认证分片头无效");int n=BitConverter.ToUInt16(a,4);if(n is <1 or >64)throw new InvalidDataException("认证分片数量无效");await write(0x19,Ready,life.Token);var parts=new SortedDictionary<int,byte[]>();while(parts.Count<n){var b=await Read(0x19);int i=b.Length>=2?BitConverter.ToUInt16(b):0;if(i<1||i>n||!parts.TryAdd(i,b[2..]))throw new InvalidDataException("认证分片序号无效");}await write(0x19,Okay,life.Token);return parts.Values.SelectMany(b=>b).ToArray();}
 public async Task Login(byte[] token,Func<Task> subscribeControl){Progress?.Invoke("酷态科问候握手");await write(0x10,[0xa4],life.Token);for(int i=0;i<2;i++){var a=await Read(0x19);if(a.Length<3||a[0]!=0||a[1]!=0||a[2]!=4)throw new InvalidDataException("酷态科问候响应无效");a[2]=5;await write(0x19,a,life.Token);}Progress?.Invoke("订阅认证控制通知");await subscribeControl();byte[] app=RandomNumberGenerator.GetBytes(16);Progress?.Invoke("发送认证随机数");await write(0x10,[0x24,0,0,0],life.Token);await SendParcel(0x19,0x0b,app,true);Progress?.Invoke("接收设备随机数");var dev=await ReceiveAuth(0x0d);if(dev.Length!=16)throw new InvalidDataException("认证随机数长度无效");Progress?.Invoke("校验设备身份");var proof=await ReceiveAuth(0x0c);keys=CuktechProtocol.Derive(token,app,dev);var expected=HMACSHA256.HashData(keys[..16],dev.Concat(app).ToArray());if(!CryptographicOperations.FixedTimeEquals(expected,proof))throw new CryptographicException("Token 与设备不匹配，请重新获取这台充电器的 Token");Progress?.Invoke("提交客户端认证");await SendParcel(0x19,0x0a,HMACSHA256.HashData(keys[16..32],app.Concat(dev).ToArray()),true);Progress?.Invoke("等待认证完成");var result=await Read(0x10);if(!result.SequenceEqual(new byte[]{0x21,0,0,0}))throw new IOException("酷态科登录未成功，请核对 Token");Progress?.Invoke("初始化加密会话");_=ReceiveLoop();var init=await Request(seq=>[5,0x20,(byte)seq,(byte)(seq>>8),0xf0]);if(init.Length!=5||init[4]!=0xf0)throw new InvalidDataException("MIOT 会话初始化失败");}
 public async Task<byte[]> Request(Func<ushort,byte[]> build){await requests.WaitAsync(life.Token);try{var seq=sequence++;if(sequence==0)sequence=1;var plain=build(seq);awaited=seq;requestFlags=plain[4];awaiting=new(TaskCreationOptions.RunContinuationsAsynchronously);if(tx>65535)throw new CryptographicException("会话计数到期，请重新连接");var counter=tx++;var cipher=CuktechProtocol.Encrypt(keys[16..32],keys[36..40],counter,plain);await SendParcel(0x1a,0,cipher,false,counter);return await awaiting.Task.WaitAsync(TimeSpan.FromSeconds(8),life.Token);}finally{awaiting=null;requests.Release();}}
 public async Task ReadProperties(params int[] ids){await Request(seq=>CuktechProtocol.Get(seq,ids));}
 public async Task SetProperty(int id,int value,int size=1,bool boolean=false){var b=await Request(seq=>CuktechProtocol.Set(seq,id,value,size,boolean));if(b.Length!=11||b[0]!=0x0b||b[4]!=1||b[5]!=1||b[6]!=2||BitConverter.ToUInt16(b,7)!=id||BitConverter.ToUInt16(b,9)!=0)throw new IOException("设备未确认此设置");await ReadProperties(id);}
 bool Matches(byte[] b)=>b.Length>=5&&b[0]==(byte)(b.Length&255)&&b[1]==0x20&&BitConverter.ToUInt16(b,2)==awaited&&(requestFlags==0xf0?b.Length==5&&b[4]==0xf0:b.Length>=6&&b[4]==(requestFlags==2?3:1));
 async Task ReceiveLoop(){try{while(!life.IsCancellationRequested){var a=await read(0x1b,life.Token);var frames=new List<(int Counter,byte[] Cipher)>();if(a.Length>=6&&a.AsSpan(0,4).SequenceEqual(new byte[]{0,0,2,0})){await write(0x1b,Ack,life.Token);frames.Add((BitConverter.ToUInt16(a,4),a[6..]));}else if(a.Length==6&&a.AsSpan(0,4).SequenceEqual(new byte[]{0,0,0,0})){int n=BitConverter.ToUInt16(a,4);if(n is <1 or >64)throw new InvalidDataException("MIOT 分片数量无效");await write(0x1b,Ready,life.Token);var parts=new SortedDictionary<int,byte[]>();int counter=-1;while(parts.Count<n){var b=await Read(0x1b);if(b.Length>=6&&b.AsSpan(0,4).SequenceEqual(new byte[]{0,0,2,0})){if(frames.Count>=16)throw new InvalidDataException("交错报文过多");await write(0x1b,Ack,life.Token);frames.Add((BitConverter.ToUInt16(b,4),b[6..]));continue;}int i=b.Length>=2?BitConverter.ToUInt16(b):0;if(i<1||i>n||b.Length<(i==1?4:2)||parts.ContainsKey(i))throw new InvalidDataException("MIOT 分片不完整或重复");if(i==1)counter=BitConverter.ToUInt16(b,2);parts[i]=b[(i==1?4:2)..];}await write(0x1b,Okay,life.Token);frames.Add((counter,parts.Values.SelectMany(b=>b).ToArray()));}else continue;
   foreach(var frame in frames.OrderBy(f=>f.Counter)){
    var b=CuktechProtocol.Decrypt(keys[..16],keys[32..36],frame.Counter,frame.Cipher);
    var disposition=receiveWindow.Accept(frame.Counter,frame.Cipher);
    Trace?.Invoke($"接收计数 {frame.Counter}，高水位 {receiveWindow.Highest}，认证通过，分类 {disposition}，标志 {(b.Length>4?b[4]:0)}，序号 {(b.Length>=4?BitConverter.ToUInt16(b,2):0)}");
    if(disposition is MiBleReceiveWindow.Result.Duplicate or MiBleReceiveWindow.Result.TooOld)continue;
    // Filter by PROPERTY, not just the last packet. A delayed C2 update must
    // survive a newer C1 packet, without rolling a newer C1 reading backwards.
    if(b.Length>=6&&b[4] is 3 or 4){
     var fresh=CuktechProtocol.Parse(b).Where(p=>!propertyCounters.TryGetValue(p.Id,out int previous)||frame.Counter>previous).ToArray();
     foreach(var property in fresh)propertyCounters[property.Id]=frame.Counter;
     if(fresh.Length>0){Properties?.Invoke(fresh);Notification?.Invoke(b);}
    }
    Trace?.Invoke($"MIOT 明文长度 {b.Length}，长度字段 {(b.Length>0?b[0]:0)}，标志 {(b.Length>4?b[4]:0)}，序号 {(b.Length>=4?BitConverter.ToUInt16(b,2):0)}，匹配等待 {Matches(b)}");
    if(Matches(b))awaiting?.TrySetResult(b);
   }
  }}catch(OperationCanceledException){}catch(Exception e){awaiting?.TrySetException(e);Failed?.Invoke(e);life.Cancel();}}
 public void Dispose(){life.Cancel();awaiting?.TrySetCanceled();if(keys.Length>0)CryptographicOperations.ZeroMemory(keys);}
}
